/**
 * A single entity that already exists in the system, as returned in the 409
 * Conflict body when the API rejects a bulk import before creating anything.
 * `type` is the entity kind ("device", "simcard", "asset", ...) and `identifier`
 * is its natural key (IMEI, SIM number, or asset name). Field names are camelCase
 * to match the API's global JSON serialization.
 */
interface ExistingEntity {
  type: string;
  identifier: string;
}

/**
 * A group of CSV rows that failed the same 400 validation check, e.g. every row
 * that is missing a Device/SIM/Asset. `rows` are the affected 1-based row numbers.
 */
interface ValidationErrorGroup {
  message: string;
  rows: number[];
}

/**
 * Parses the flattened FluentValidation message the API returns on a 400 bulk
 * import rejection into per-row failures, then groups them by message.
 *
 * NOTE: this deliberately parses a human-readable string rather than consuming a
 * structured array. Unlike the 409 path (which returns `existingEntities`), the
 * backend 400 handler only serializes `exception.Message` — a newline-joined list
 * of "Devices[N]: <message> Severity: <level>" entries prefixed "Validation failed:".
 * A proper fix is to have the API project `ValidationException.Errors` into a
 * structured array (follow-up on the backend); until then we parse here and fall
 * back to the raw message if the format is not recognised.
 */
function parseValidationErrors(message: string): ValidationErrorGroup[] {
  if (message === null || message === undefined || message === '') return [];

  // Each failure is "Devices[N]: <message> Severity: <level>". Capture the row
  // index and the message, tolerating the "Validation failed:" prefix and the
  // newline/space separators FluentValidation uses.
  const entryPattern = /Devices\[(\d+)\]:\s*(.+?)\s*Severity:\s*\w+/gis;

  const byMessage = new Map<string, number[]>();
  let match: RegExpExecArray | null;
  while ((match = entryPattern.exec(message)) !== null) {
    const zeroBasedRow = Number(match[1]);
    const text = match[2].trim();
    const rows = byMessage.get(text) ?? [];
    rows.push(zeroBasedRow + 1); // present 1-based row numbers to the user
    byMessage.set(text, rows);
  }

  return Array.from(byMessage.entries()).map(([msg, rows]) => ({
    message: msg,
    rows: rows.sort((a, b) => a - b),
  }));
}

/**
 * Collapses a sorted list of row numbers into a compact range string, e.g.
 * [1,2,3,384] -> "1-3, 384". Keeps the grouped 400 view to one line per error
 * even when hundreds of consecutive rows fail.
 */
function formatRowRanges(rows: number[]): string {
  if (rows.length === 0) return '';
  const parts: string[] = [];
  let start = rows[0];
  let prev = rows[0];
  for (let i = 1; i <= rows.length; i++) {
    const current = rows[i];
    if (current === prev + 1) {
      prev = current;
      continue;
    }
    parts.push(start === prev ? `${start}` : `${start}-${prev}`);
    start = current;
    prev = current;
  }
  return parts.join(', ');
}

@Component({
  selector: 'app-bulk-import-dialog',
  imports: [
    CommonModule,
    ButtonModule,
    FileUploadModule,
    ProgressBarModule,
    MessageModule,
    TranslatePipe,
    ImportErrorTableComponent,
  ],
  templateUrl: './bulk-import-dialog.component.html',
  styleUrl: './bulk-import-dialog.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class BulkImportDialogComponent implements OnInit {
  private readonly bulkImportService = inject(BulkImportService);
  private readonly dialogRef = inject(DynamicDialogRef);
  private readonly dialogConfig = inject(DynamicDialogConfig);
  private readonly destroyRef = inject(DestroyRef);
  private readonly broadcastService = inject(BroadcastEventMessageService);
  private readonly toastService = inject(ToastService);
  private readonly entitiesService = inject(EntitiesService);
  private readonly adminStateService = inject(AdminStateService);

  readonly ownerId = signal<string>('');
  readonly clientName = signal<string>('');
  readonly selectedFile = signal<File | null>(null);
  readonly isUploading = signal(false);
  readonly uploadProgress = signal(0);
  readonly importResult = signal<BulkImportResponse | null>(null);
  readonly errorMessage = signal<string | null>(null);
  readonly existingEntities = signal<ExistingEntity[]>([]);
  readonly validationErrors = signal<ValidationErrorGroup[]>([]);
  readonly isLoadingTemplate = signal(false);

  readonly maxFileSize = 10 * 1024 * 1024; // 10MB

  // --- Result banner (A) ---------------------------------------------------
  // Overall outcome of a completed import, driving the banner severity/message.
  readonly resultState = computed<'success' | 'partial' | 'error' | null>(
    () => {
      const result = this.importResult();
      if (!result) return null;
      if (result.successCount === 0) return 'error';
      if (result.failureCount > 0) return 'partial';
      return 'success';
    },
  );

  readonly resultSeverity = computed<'success' | 'warn' | 'error'>(() => {
    const state = this.resultState();
    if (state === 'success') return 'success';
    if (state === 'partial') return 'warn';
    return 'error';
  });

  // --- Wrong-file hint (B) -------------------------------------------------
  // The classic mistake is uploading an export file (wrong columns), which makes
  // every row fail the same "must contain an entity" check. Detect that shape so
  // we can nudge the user to the template instead of just showing a table.
  readonly looksLikeWrongFile = computed<boolean>(() => {
    const groups = this.validationErrors();
    if (groups.length !== 1) return false;
    return groups[0].message
      .toLowerCase()
      .includes('must contain at least one entity');
  });

  // --- Unified error tables (D) --------------------------------------------
  readonly existingEntityColumns: ImportErrorColumn[] = [
    {
      headerKey: 'ADMIN.SHARED.BULK_IMPORT.COLUMNS.TYPE',
      field: 'type',
      widthClass: 'w-38',
    },
    {
      headerKey: 'ADMIN.SHARED.BULK_IMPORT.COLUMNS.IDENTIFIER',
      field: 'identifier',
    },
  ];

  readonly validationColumns: ImportErrorColumn[] = [
    {
      headerKey: 'ADMIN.SHARED.BULK_IMPORT.COLUMNS.ROWS',
      field: 'rowsLabel',
      widthClass: 'w-38',
    },
    { headerKey: 'ADMIN.SHARED.BULK_IMPORT.COLUMNS.MESSAGE', field: 'message' },
  ];

  readonly rowErrorColumns: ImportErrorColumn[] = [
    {
      headerKey: 'ADMIN.SHARED.BULK_IMPORT.COLUMNS.ROW',
      field: 'rowNumber',
      widthClass: 'w-20',
    },
    {
      headerKey: 'ADMIN.SHARED.BULK_IMPORT.COLUMNS.FIELD',
      field: 'fieldLabel',
      widthClass: 'w-38',
    },
    { headerKey: 'ADMIN.SHARED.BULK_IMPORT.COLUMNS.MESSAGE', field: 'message' },
  ];

  // Rows shaped for the unified table (pre-format ranges / field fallbacks so the
  // table component stays a dumb renderer).
  readonly validationRows = computed(() =>
    this.validationErrors().map((group) => ({
      rowsLabel: `${group.rows.length} (${formatRowRanges(group.rows)})`,
      message: group.message,
    })),
  );

  readonly importErrorRows = computed(() =>
    (this.importResult()?.errors ?? []).map((error) => ({
      rowNumber: error.rowNumber,
      fieldLabel:
        error.field !== null && error.field !== undefined && error.field !== ''
          ? error.field
          : '-',
      message: error.message,
    })),
  );

  // Template data
  private deviceTypes: string[] = [];
  private assetTypes: string[] = [];
  private costCentres: string[] = [];
  private assetGroups: string[] = [];
  private primaryColor = '#1976d2'; // Default blue color

  constructor() {
    const ownerId = this.dialogConfig.data?.['ownerId'];
    if (ownerId !== null && ownerId !== undefined) {
      this.ownerId.set(ownerId);
    }

    const clientName = this.dialogConfig.data?.['clientName'];
    if (clientName !== null && clientName !== undefined) {
      this.clientName.set(clientName);
    } else {
      // Fallback to get from admin state
      const selectedClient = this.adminStateService.selectedClient();
      if (selectedClient?.name !== null && selectedClient?.name !== undefined) {
        this.clientName.set(selectedClient.name);
      }
    }

    // Get primary color from CSS variable or client theme
    this.getPrimaryColor();
  }

  private getPrimaryColor(): void {
    try {
      // Try to get the primary color from CSS variables
      const primaryColor = getComputedStyle(
        document.documentElement,
      ).getPropertyValue('--primary-color');
      if (
        primaryColor !== null &&
        primaryColor !== undefined &&
        primaryColor.trim() !== ''
      ) {
        this.primaryColor = primaryColor.trim();
      }
    } catch {
      console.warn('Could not get primary color, using default');
    }
  }

  ngOnInit(): void {
    this.loadTemplateData();
  }

  private loadTemplateData(): void {
    const ownerId = this.ownerId();
    if (ownerId === null || ownerId === undefined || ownerId === '') return;

    this.isLoadingTemplate.set(true);

    forkJoin({
      deviceTypes: this.entitiesService.listDeviceTypes(ownerId),
      assetTypes: this.entitiesService.listAssetTypes(ownerId),
      costCentres: this.entitiesService.listCostCentres(ownerId),
      assetGroups: this.entitiesService.listAssetGroups(ownerId),
    })
      .pipe(
        takeUntilDestroyed(this.destroyRef),
        finalize(() => this.isLoadingTemplate.set(false)),
      )
      .subscribe({
        next: (data) => {
          this.deviceTypes = data.deviceTypes.items
            .map((dt) => dt.name)
            .filter(
              (name): name is string => name !== null && name !== undefined,
            )
            .sort();
          this.assetTypes = data.assetTypes.items
            .map((at) => at.name)
            .filter(
              (name): name is string => name !== null && name !== undefined,
            )
            .sort();
          this.costCentres = data.costCentres.items
            .map((cc) => cc.name)
            .filter(
              (name): name is string => name !== null && name !== undefined,
            )
            .sort();
          this.assetGroups = data.assetGroups.items
            .map((ag) => ag.name)
            .filter(
              (name): name is string => name !== null && name !== undefined,
            )
            .sort();
        },
        error: () => {
          this.toastService.showWarning(
            'Template Data',
            'Could not load all dropdown options. Template will be generated with basic structure.',
          );
        },
      });
  }

  onFileSelect(event: FileSelectEvent): void {
    this.errorMessage.set(null);
    this.existingEntities.set([]);
    this.validationErrors.set([]);
    this.importResult.set(null);

    const file = event.files[0];
    if (file === null || file === undefined) {
      return;
    }

    // Validate file extension
    const extension = file.name.split('.').pop()?.toLowerCase();
    if (extension !== 'csv') {
      this.errorMessage.set('Only CSV files are supported');
      this.selectedFile.set(null);
      return;
    }

    // Validate file size
    if (file.size > this.maxFileSize) {
      this.errorMessage.set('File size cannot exceed 10MB');
      this.selectedFile.set(null);
      return;
    }

    this.selectedFile.set(file);
  }

  onUpload(): void {
    const file = this.selectedFile();
    const ownerId = this.ownerId();

    if (
      file === null ||
      file === undefined ||
      ownerId === null ||
      ownerId === undefined ||
      ownerId === ''
    ) {
      this.errorMessage.set('No file selected or owner ID not provided');
      return;
    }

    this.isUploading.set(true);
    this.uploadProgress.set(0);
    this.errorMessage.set(null);
    this.existingEntities.set([]);
    this.validationErrors.set([]);
    this.importResult.set(null);

    this.bulkImportService
      .bulkImportDevices(ownerId, file, 'body', true)
      .pipe(
        takeUntilDestroyed(this.destroyRef),
        finalize(() => {
          this.isUploading.set(false);
          this.uploadProgress.set(100);
        }),
      )
      .subscribe({
        next: (response: BulkImportResponse) => {
          this.importResult.set(response);

          if (response.successCount > 0) {
            this.toastService.showSuccess(
              'Import Complete',
              `Successfully imported ${response.successCount} device(s)`,
            );
            // Broadcast entity update to refresh grids
            this.broadcastService.broadcast('entity-updated', {
              entityType: 'devices',
              operation: 'create',
            });
          }

          if (response.failureCount > 0) {
            this.toastService.showWarning(
              'Import Completed with Errors',
              `${response.failureCount} row(s) failed to import. See details below.`,
            );
          }
        },
        error: (caught: unknown) => {
          // The auth interceptor flattens HTTP errors into an ApiErrorResponse and
          // attaches the raw HttpErrorResponse as `originalError`. Unwrap that so we
          // get the real status + body; fall back to `caught` itself if the request
          // ever reaches us without the interceptor's wrapping.
          const wrapper = caught as {
            errorMessage?: string;
            originalError?: HttpErrorResponse;
          };
          const httpError = (wrapper?.originalError ??
            caught) as HttpErrorResponse;

          const status = httpError?.status;
          // The 400 path returns the body as a raw string, the 409 path as a
          // JSON object; normalise so we can read the server detail from either.
          const errorBody = httpError?.error;
          const bodyObject =
            typeof errorBody === 'object' && errorBody !== null
              ? (errorBody as {
                  message?: string;
                  existingEntities?: ExistingEntity[];
                })
              : null;
          const serverMessage =
            typeof errorBody === 'string' ? errorBody : bodyObject?.message;

          const hasText = (v: string | undefined): v is string =>
            v !== null && v !== undefined && v !== '';

          const errorMsg = hasText(serverMessage)
            ? serverMessage
            : hasText(wrapper?.errorMessage)
              ? wrapper.errorMessage
              : hasText(httpError?.message)
                ? httpError.message
                : 'An error occurred during bulk import';

          // A 409 pre-validation rejection carries the full list of colliding
          // entities; surface them so the user sees exactly what already exists.
          if (status === 409 && Array.isArray(bodyObject?.existingEntities)) {
            this.existingEntities.set(bodyObject.existingEntities);
          }

          // A 400 rejection returns per-row validation failures as a flattened
          // string; parse and group them so the user sees which rows to fix
          // instead of a wall of text. Falls back to the plain message below if
          // the format is not recognised (validationErrors stays empty).
          if (status === 400 && hasText(serverMessage)) {
            this.validationErrors.set(parseValidationErrors(serverMessage));
          }

          // Only show the raw message box when there's no richer structured view;
          // otherwise the wall-of-text string would render above the grouped table.
          const hasStructuredView =
            this.existingEntities().length > 0 ||
            this.validationErrors().length > 0;
          this.errorMessage.set(hasStructuredView ? null : errorMsg);

          // Keep the toast short when the detail is already shown in a table.
          this.toastService.showError(
            'Import Failed',
            hasStructuredView ? 'See the details below.' : errorMsg,
          );
        },
      });
  }

  onCancel(): void {
    this.dialogRef.close();
  }

  onClose(): void {
    const result = this.importResult();
    this.dialogRef.close(result);
  }

  async downloadTemplate(): Promise<void> {
    const clientName = this.clientName() || 'Client';
    const fileName = `${clientName} - Bulk Import Template.xlsx`;

    try {
      // Create workbook
      const workbook = new ExcelJS.Workbook();
      workbook.creator = 'CypherView';
      workbook.created = new Date();

      // Create main worksheet
      const worksheet = workbook.addWorksheet('Import Data', {
        properties: { tabColor: { argb: this.hexToArgb(this.primaryColor) } },
      });

      // Define headers
      const headers = [
        'DeviceSerialNr',
        'DeviceIMEI',
        'DeviceUnitType',
        'Device_PreTested',
        'Device_Comment',
        'SimCard_SIMNumber',
        'SimCard_VoiceNumber',
        'SimCard_Network',
        'SimCard_Comment',
        'AssetName',
        'AssetTypeName',
        'AssetCostCentreName',
        'AssetGroupNames',
        'AssetComment',
      ];

      // Add header row
      const headerRow = worksheet.addRow(headers);

      // Style header row
      const primaryColorArgb = this.hexToArgb(this.primaryColor);
      headerRow.eachCell((cell, colNumber) => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = {
          type: 'pattern',
          pattern: 'solid',
          fgColor: { argb: primaryColorArgb },
        };
        cell.alignment = { horizontal: 'center', vertical: 'middle' };
        cell.border = {
          top: { style: 'thin' },
          left: { style: 'thin' },
          bottom: { style: 'thin' },
          right: { style: 'thin' },
        };

        // Add comment/note to SimCard_SIMNumber column (column 6)
        if (colNumber === 6) {
          cell.note = {
            texts: [
              {
                font: { bold: true, size: 10, color: { argb: 'FF000000' } },
                text: 'International Format Required:\n',
              },
              {
                font: { size: 9, color: { argb: 'FF000000' } },
                text: "SIM number must start with '+' followed by the country code.\n\nExample: +27123456789\n\nNumbers without the '+' prefix will be rejected.",
              },
            ],
            margins: {
              insetmode: 'custom',
              inset: [0.13, 0.13, 0.25, 0.25],
            },
          };
        }

        // Add comment/note to AssetGroupNames column (column 13)
        if (colNumber === 13) {
          cell.note = {
            texts: [
              {
                font: { bold: true, size: 10, color: { argb: 'FF000000' } },
                text: 'Multiple Groups:\n',
              },
              {
                font: { size: 9, color: { argb: 'FF000000' } },
                text: 'You can enter multiple asset groups separated by commas.\n\nExample: Fleet,VIP,Premium\n\nUse the dropdown to see available groups, then manually type multiple values separated by commas.',
              },
            ],
            margins: {
              insetmode: 'custom',
              inset: [0.13, 0.13, 0.25, 0.25],
            },
          };
        }
      });

      // Set column widths
      worksheet.columns = [
        { width: 18 }, // DeviceSerialNr
        { width: 20 }, // DeviceIMEI
        { width: 20 }, // DeviceUnitType
        { width: 18 }, // Device_PreTested
        { width: 25 }, // Device_Comment
        { width: 24 }, // SimCard_SIMNumber
        { width: 24 }, // SimCard_VoiceNumber
        { width: 20 }, // SimCard_Network
        { width: 20 }, // SimCard_Comment
        { width: 15 }, // AssetName
        { width: 20 }, // AssetTypeName
        { width: 25 }, // AssetCostCentreName
        { width: 20 }, // AssetGroupNames
        { width: 25 }, // AssetComment
      ];

      // Add sample data rows
      worksheet.addRow([
        '1234567890',
        '123456789012345',
        this.deviceTypes[0] || 'GPS Tracker',
        '1',
        'Test device comment',
        '+27123456789',
        '+27123456789',
        'Vodacom',
        'SIM comment',
        'Vehicle 1',
        this.assetTypes[0] || 'Vehicle',
        this.costCentres[0] || 'Default',
        this.assetGroups[0] || 'Fleet',
        'Asset comment',
      ]);

      worksheet.addRow([
        '1234567891',
        '123456789012346',
        this.deviceTypes[0] || 'GPS Tracker',
        '0',
        'Another device',
        '+27123456790',
        '+27123456790',
        'MTN',
        'Another SIM',
        'Vehicle 2',
        this.assetTypes[1] || 'Trailer',
        this.costCentres[1] || 'Sales',
        `${this.assetGroups[0] || 'Fleet'},${this.assetGroups[1] || 'VIP'}`,
        'Second asset',
      ]);

      // Add data validations for dropdowns
      if (this.deviceTypes.length > 0) {
        worksheet
          .getColumn(3)
          .eachCell({ includeEmpty: true }, (cell, rowNumber) => {
            if (rowNumber > 1) {
              // Skip header row
              cell.dataValidation = {
                type: 'list',
                allowBlank: true,
                formulae: [`"${this.deviceTypes.join(',')}"`],
                showErrorMessage: true,
                errorStyle: 'warning',
                errorTitle: 'Invalid Value',
                error: 'Please select a valid Device Type from the dropdown',
              };
            }
          });
      }

      if (this.assetTypes.length > 0) {
        worksheet
          .getColumn(11)
          .eachCell({ includeEmpty: true }, (cell, rowNumber) => {
            if (rowNumber > 1) {
              cell.dataValidation = {
                type: 'list',
                allowBlank: true,
                formulae: [`"${this.assetTypes.join(',')}"`],
                showErrorMessage: true,
                errorStyle: 'warning',
                errorTitle: 'Invalid Value',
                error: 'Please select a valid Asset Type from the dropdown',
              };
            }
          });
      }

      if (this.costCentres.length > 0) {
        worksheet
          .getColumn(12)
          .eachCell({ includeEmpty: true }, (cell, rowNumber) => {
            if (rowNumber > 1) {
              cell.dataValidation = {
                type: 'list',
                allowBlank: true,
                formulae: [`"${this.costCentres.join(',')}"`],
                showErrorMessage: true,
                errorStyle: 'warning',
                errorTitle: 'Invalid Value',
                error: 'Please select a valid Cost Centre from the dropdown',
              };
            }
          });
      }

      if (this.assetGroups.length > 0) {
        worksheet
          .getColumn(13)
          .eachCell({ includeEmpty: true }, (cell, rowNumber) => {
            if (rowNumber > 1) {
              // Set data validation - simple dropdown, no hints in cells
              cell.dataValidation = {
                type: 'list',
                allowBlank: true,
                formulae: [`"${this.assetGroups.join(',')}"`],
                showErrorMessage: false, // Don't show error, allow custom values
              };
            }
          });
      }

      // Create Reference Data worksheet
      const refWorksheet = workbook.addWorksheet('Reference Data', {
        properties: {
          tabColor: {
            argb: this.hexToArgb(this.getLighterColor(this.primaryColor)),
          },
        },
      });

      const maxLength = Math.max(
        this.deviceTypes.length,
        this.assetTypes.length,
        this.costCentres.length,
        this.assetGroups.length,
      );

      // Add reference headers
      const refHeaderRow = refWorksheet.addRow([
        'Available Device Types',
        'Available Asset Types',
        'Available Cost Centres',
        'Available Asset Groups',
      ]);

      // Style reference headers
      const lighterColorArgb = this.hexToArgb(
        this.getLighterColor(this.primaryColor),
      );
      refHeaderRow.eachCell((cell) => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = {
          type: 'pattern',
          pattern: 'solid',
          fgColor: { argb: lighterColorArgb },
        };
        cell.alignment = { horizontal: 'center', vertical: 'middle' };
        cell.border = {
          top: { style: 'thin' },
          left: { style: 'thin' },
          bottom: { style: 'thin' },
          right: { style: 'thin' },
        };
      });

      // Add reference data
      for (let i = 0; i < maxLength; i++) {
        refWorksheet.addRow([
          this.deviceTypes[i] || '',
          this.assetTypes[i] || '',
          this.costCentres[i] || '',
          this.assetGroups[i] || '',
        ]);
      }

      // Set column widths for reference sheet
      refWorksheet.columns = [
        { width: 25 },
        { width: 25 },
        { width: 25 },
        { width: 25 },
      ];

      // Generate Excel file and download
      const buffer = await workbook.xlsx.writeBuffer();
      const blob = new Blob([buffer], {
        type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = fileName;

      try {
        link.click();
      } finally {
        window.URL.revokeObjectURL(url);
      }

      this.toastService.showSuccess(
        'Download Complete',
        'Template downloaded. Please save as CSV before uploading.',
      );
    } catch (error) {
      this.toastService.showError(
        'Template Generation Failed',
        'An error occurred while generating the template. Please try again.',
      );
      throw error;
    }
  }

  get hasErrors(): boolean {
    const result = this.importResult();
    return result ? result.errors.length > 0 : false;
  }

  get canUpload(): boolean {
    return !!this.selectedFile() && !this.isUploading();
  }

  /** Clear the selected file and any prior error state (C: file chip remove). */
  clearFile(): void {
    this.selectedFile.set(null);
    this.errorMessage.set(null);
    this.existingEntities.set([]);
    this.validationErrors.set([]);
  }

  /**
   * Convert hex color to ARGB format for ExcelJS (with alpha channel)
   * @param hex Hex color string (e.g., '#1976d2' or 'rgb(25, 118, 210)')
   * @returns ARGB string (e.g., 'FF1976D2')
   */
  private hexToArgb(hex: string): string {
    // Handle rgb/rgba format
    if (hex.startsWith('rgb')) {
      const match = hex.match(/\d+/g);
      if (match && match.length >= 3) {
        const rgb = match
          .slice(0, 3)
          .map((x) => parseInt(x).toString(16).padStart(2, '0'))
          .join('')
          .toUpperCase();
        return `FF${rgb}`; // FF for full opacity
      }
    }

    // Handle hex format
    hex = hex.replace('#', '');
    if (hex.length === 3) {
      hex = hex
        .split('')
        .map((x) => x + x)
        .join('');
    }
    return `FF${hex.toUpperCase()}`; // Add alpha channel
  }

  /**
   * Convert hex color to RGB format (without alpha)
   * @param hex Hex color string
   * @returns RGB string without # (e.g., '1976D2')
   */
  private hexToRgb(hex: string): string {
    return this.hexToArgb(hex).substring(2); // Remove FF alpha channel
  }

  /**
   * Get a lighter version of the color for the second tab
   * @param color Hex color string
   * @returns Lighter hex color string
   */
  private getLighterColor(color: string): string {
    // Convert to RGB
    const rgb = this.hexToRgb(color);
    const r = parseInt(rgb.substring(0, 2), 16);
    const g = parseInt(rgb.substring(2, 4), 16);
    const b = parseInt(rgb.substring(4, 6), 16);

    // Make it lighter by blending with white (increase by 40%)
    const lighter = (val: number) =>
      Math.min(255, Math.floor(val + (255 - val) * 0.4));

    const newR = lighter(r).toString(16).padStart(2, '0');
    const newG = lighter(g).toString(16).padStart(2, '0');
    const newB = lighter(b).toString(16).padStart(2, '0');

    return `#${newR}${newG}${newB}`;
  }
}
