import {
  ChangeDetectionStrategy,
  Component,
  computed,
  input,
  signal,
} from '@angular/core';
import { TableModule } from 'primeng/table';
import { ButtonModule } from 'primeng/button';
import { TranslatePipe } from '@ngx-translate/core';

export interface ImportErrorColumn {
  /** Translation key for the column header. */
  headerKey: string;
  /** Key on each row object whose value is rendered in this column. */
  field: string;
  /** Optional fixed width class (e.g. 'w-20', 'w-38'). */
  widthClass?: string;
}

/**
 * Reusable table for the bulk-import dialog's three error/collision lists
 * (existing entities, grouped validation errors, per-row import errors). Keeps a
 * single consistent look and collapses very long lists behind a "Show all" toggle.
 */
@Component({
  selector: 'app-import-error-table',
  imports: [TableModule, ButtonModule, TranslatePipe],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './import-error-table.component.html',
})
export class ImportErrorTableComponent {
  readonly titleKey = input.required<string>();
  readonly columns = input.required<ImportErrorColumn[]>();
  // Accept any object rows; the table only reads the fields named in `columns`.
  readonly rows = input.required<object[]>();

  /** Rows beyond this count are hidden behind a "Show all" toggle. */
  readonly collapseThreshold = input<number>(50);

  protected readonly showAll = signal(false);

  protected readonly isTruncated = computed(
    () => !this.showAll() && this.rows().length > this.collapseThreshold(),
  );

  protected readonly visibleRows = computed(() =>
    this.isTruncated()
      ? this.rows().slice(0, this.collapseThreshold())
      : this.rows(),
  );

  /** Narrow a row to an indexable record for the template's dynamic column read. */
  protected asRecord(row: object): Record<string, unknown> {
    return row as Record<string, unknown>;
  }
}
